"""Closed form vs brute-force enumeration of proper colorings of F_n."""
from __future__ import annotations
from itertools import product
from typing import List, Tuple

Vertex = Tuple[int, int]
CENTER: Vertex = (-1, -1)


def friendship_vertices(n: int) -> List[Vertex]:
    verts: List[Vertex] = [CENTER]
    for i in range(n):
        verts += [(i, 0), (i, 1)]
    return verts


def friendship_edges(n: int) -> List[Tuple[Vertex, Vertex]]:
    edges: List[Tuple[Vertex, Vertex]] = []
    for i in range(n):
        edges += [(CENTER, (i, 0)), (CENTER, (i, 1)), ((i, 0), (i, 1))]
    return edges


def closed_form(n: int, q: int) -> int:
    return q * ((q - 1) * (q - 2)) ** n


def brute_force(n: int, q: int) -> int:
    verts, edges = friendship_vertices(n), friendship_edges(n)
    count = 0
    for a in product(range(q), repeat=len(verts)):
        c = dict(zip(verts, a))
        if all(c[u] != c[v] for u, v in edges):
            count += 1
    return count


if __name__ == "__main__":
    for n in range(4):
        for q in range(5):
            assert closed_form(n, q) == brute_force(n, q)
            print(f"n={n} q={q}: {closed_form(n, q)}")
    print("closed form matches brute force everywhere")

"""The six-basic-emotions count P(F_n, 6) = 6 * 20^n, with sanity checks."""
from __future__ import annotations


def emotions_count(n: int) -> int:
    return 6 * ((6 - 1) * (6 - 2)) ** n


if __name__ == "__main__":
    for n in range(9):
        val = emotions_count(n)
        assert val == 6 * 20 ** n
        print(f"n={n:>2}: P(F_n, 6) = 6 * 20^{n} = {val:,}")

