    count <- 0
    for each map c: V -> {0,...,q-1}:
        if for all (u,v) in E: c[u] != c[v]:
            count <- count + 1
    return count

function EMO_CHROM(n, floor=3, cap=6):
    k <- floor
    while k * ((k-1)*(k-2))^n == 0:
        k <- k + 1
        if k > cap: fail
